package sohal.lld.zerodha.command;import sohal.lld.zerodha.broker.StockExchange;import sohal.lld.zerodha.exception.InsufficientStockException;import sohal.lld.zerodha.order.Order;import sohal.lld.zerodha.user.Account;public class SellOrderCommand implements OrderCommand {    private final Account account;    private final Order order;    private final StockExchange stockExchange;    public SellOrderCommand(Account account, Order order) {        this.account = account;        this.order = order;        this.stockExchange = StockExchange.getInstance();    }    @Override    public void execute() {        if(account.getStockQuantity(order.getStock().getSymbol()) < order.getQuantity()) {            throw new InsufficientStockException("Not enough shares of " + order.getStock().getSymbol());        }        System.out.printf("Placing SELL order %s for %d quantity of %s.%n", order.getOrderId(), order.getQuantity(), order.getStock().getSymbol());        stockExchange.placeSellOrder(order);    }}